import * as T from '../vendor/three.module.js';
const rubber=new T.MeshStandardMaterial({color:'#141c1d',roughness:.91});
const chrome=new T.MeshStandardMaterial({color:'#9faead',metalness:.85,roughness:.28});
const black=new T.MeshStandardMaterial({color:'#1b2525',roughness:.7});
const glass=new T.MeshPhysicalMaterial({color:'#556f78',metalness:.3,roughness:.1,clearcoat:1});
const light=new T.MeshStandardMaterial({color:'#eeecd6',emissive:'#e2e5c7',emissiveIntensity:.3,roughness:.2});
const red=new T.MeshStandardMaterial({color:'#9f201b',emissive:'#ff3020',emissiveIntensity:.25});
const boxGeometry=new T.BoxGeometry(1,1,1);
function box(group,mat,x,y,z,w,h,d){const m=new T.Mesh(boxGeometry,mat);m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
function shell(sections,material){const verts=[],indices=[];for(const [z,w,bottom,top] of sections){verts.push(-w*.89,bottom,z,-w,top-.13,z,-w*.82,top,z,w*.82,top,z,w,top-.13,z,w*.89,bottom,z);}for(let k=0;k<sections.length-1;k++)for(let j=0;j<6;j++){const a=k*6+j,b=k*6+(j+1)%6,c=a+6,d=b+6;indices.push(a,c,b,b,c,d);}indices.push(0,1,2,0,2,3,0,3,4,0,4,5);let n=(sections.length-1)*6;indices.push(n,n+2,n+1,n,n+3,n+2,n,n+4,n+3,n,n+5,n+4);const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();const m=new T.Mesh(g,material);m.castShadow=true;m.receiveShadow=true;return m;}
export function createCar(color='#d8dcd4',{player=false,van=false}={}){const root=new T.Group(),exterior=new T.Group(),interior=new T.Group();root.add(exterior,interior);const paint=new T.MeshPhysicalMaterial({color,metalness:.58,roughness:.26,clearcoat:1,clearcoatRoughness:.15});const tail=red.clone();const height=van?.15:0;
 exterior.add(shell([[-2.23,.69,.45,.71],[-1.95,.86,.35,.89],[-.95,.91,.34,1.01],[.8,.91,.34,1.02],[1.95,.86,.41,.88],[2.17,.73,.48,.78]],paint));
 exterior.add(shell([[-1.02,.77,.97,1.0],[-.32,.7,1,1.5+height],[.68,.7,1,1.52+height],[1.34,.77,.97,1.04]],glass));
 const roof=box(exterior,paint,.0,1.52+height,.22,1.29,.07,1.04);roof.rotation.x=-.015;
 // Narrow pillars, chrome window surrounds, door seams and handles.
 for(const s of [-1,1]){box(exterior,paint,s*.71,1.28+height*.5,.55,.048,.52,.07);let p=box(exterior,paint,s*.71,1.25+height*.5,-.64,.047,.64,.06);p.rotation.x=.85;let q=box(exterior,paint,s*.72,1.27+height*.5,1,.055,.69,.06);q.rotation.x=-.77;box(exterior,chrome,s*.797,1.01,.18,.025,.025,2.37);box(exterior,black,s*.897,.66,.47,.015,.53,.012);for(const z of [.25,1.25])box(exterior,chrome,s*.9,.92,z,.025,.04,.21);box(exterior,paint,s*1.0,1.04,-.6,.26,.18,.33);box(exterior,black,s*1.015,1.04,-.418,.2,.13,.018);box(exterior,black,s*.83,.4,0,.17,.15,2.8);}
 box(exterior,black,0,.55,-2.195,1.08,.18,.045);for(let i=0;i<5;i++)box(exterior,chrome,0,.49+i*.03,-2.224,1,.008,.01);
 for(const s of [-1,1]){const head=box(exterior,light,s*.57,.77,-2.025,.45,.1,.12);head.rotation.y=s*-.23;box(exterior,tail,s*.62,.8,2.06,.42,.16,.11);box(exterior,chrome,s*.68,.5,2.1,.15,.075,.1);}
 box(exterior,light,0,.58,2.176,.47,.17,.012);box(exterior,light,0,.51,-2.23,.47,.15,.012);
 const badge=box(exterior,chrome,0,.77,-2.15,.1,.08,.045);badge.rotation.z=Math.PI/4;
 const wheels=[],front=[];const tireGeo=new T.CylinderGeometry(.32,.32,.21,24),rimGeo=new T.CylinderGeometry(.228,.228,.219,18);tireGeo.rotateZ(Math.PI/2);rimGeo.rotateZ(Math.PI/2);
 for(const x of [-.88,.88])for(const z of [-1.37,1.36]){const pivot=new T.Group();pivot.position.set(x,.34,z);const spin=new T.Group();pivot.add(spin);const tire=new T.Mesh(tireGeo,rubber);tire.castShadow=true;spin.add(tire);const rim=new T.Mesh(rimGeo,black);spin.add(rim);for(let j=0;j<7;j++){const a=j/7*Math.PI*2;const spoke=box(spin,chrome,Math.sign(x)*.12,Math.sin(a)*.12,Math.cos(a)*.12,.023,.045,.22);spoke.rotation.x=-a;}box(spin,chrome,Math.sign(x)*.132,0,0,.025,.07,.07);exterior.add(pivot);wheels.push(spin);if(z<0)front.push(pivot);}
 if(player){
  const dash=new T.MeshStandardMaterial({color:'#1b2929',roughness:.98});const seatmat=new T.MeshStandardMaterial({color:'#343e39',roughness:1});
  box(interior,dash,0,.98,-.65,1.75,.2,.58);box(interior,dash,0,.89,-.32,1.7,.2,.19);box(interior,chrome,0,.925,-.20,1.57,.015,.024);
  for(const x of [-.63,.02,.62]){box(interior,black,x,.995,-.345,.27,.1,.015);for(let j=0;j<4;j++)box(interior,chrome,x,.958+j*.023,-.331,.23,.005,.006);}
  box(interior,black,0,1.17,-.67,.36,.23,.026);box(interior,new T.MeshBasicMaterial({color:'#476957'}),0,1.17,-.65,.32,.19,.008);
  box(interior,dash,.42,1.05,-.57,.49,.16,.28);
  for(const x of [-.44,.44]){box(interior,seatmat,x,.48,.65,.58,.16,.61);const back=box(interior,seatmat,x,.87,.95,.59,.76,.15);back.rotation.x=-.13;box(interior,seatmat,x,1.33,1.0,.31,.22,.13);}
  const wheel=new T.Mesh(new T.TorusGeometry(.19,.025,8,40),black);wheel.position.set(.43,1.02,-.16);wheel.rotation.x=-.2;interior.add(wheel);const hub=new T.Group();hub.position.copy(wheel.position);hub.rotation.x=-.2;box(hub,black,0,0,0,.13,.08,.04);box(hub,chrome,0,-.08,0,.028,.13,.025);box(hub,chrome,0,0,0,.33,.025,.02);interior.add(hub);interior.userData.wheel=wheel;interior.userData.hub=hub;
 }
 return {root,exterior,interior,wheels,front,tail,animate(steer,speed,dt,brake){front.forEach(p=>p.rotation.y=-steer);wheels.forEach(w=>w.rotation.x-=speed*dt/.32);tail.emissiveIntensity=brake?2:.25;if(interior.userData.wheel){interior.userData.wheel.rotation.z=-steer*15.9;interior.userData.hub.rotation.z=-steer*15.9;}}};}
export function createPerson(child=false){const root=new T.Group();const skin=new T.MeshStandardMaterial({color:'#c89b77',roughness:.95});const shirt=new T.MeshStandardMaterial({color:child?'#f0b448':'#e5e0d6',roughness:1});const pants=new T.MeshStandardMaterial({color:'#354c60',roughness:1});const s=child?.7:1;const head=new T.Mesh(new T.SphereGeometry(.135,10,8),skin);head.position.y=1.58;root.add(head);const hair=new T.Mesh(new T.SphereGeometry(.14,10,8,0,Math.PI*2,0,Math.PI*.55),black);hair.position.y=1.61;root.add(hair);box(root,shirt,0,1.19,0,.36,.53,.23);if(child){box(root,new T.MeshStandardMaterial({color:'#9d3731'}),0,1.2,.18,.3,.38,.15);const hat=new T.Mesh(new T.CylinderGeometry(.2,.2,.035,14),shirt);hat.position.y=1.7;root.add(hat);}
 const limbs=[];for(const x of [-.12,.12]){const leg=new T.Group();leg.position.set(x,.94,0);box(leg,pants,0,-.36,0,.13,.7,.15);box(leg,black,0,-.75,-.055,.16,.12,.27);root.add(leg);limbs.push(leg);}for(const x of [-.24,.24]){const arm=new T.Group();arm.position.set(x,1.4,0);box(arm,shirt,0,-.14,0,.12,.29,.13);box(arm,skin,0,-.37,0,.09,.2,.1);root.add(arm);limbs.push(arm);}root.scale.setScalar(s);return {root,limbs,child};}
export function createTram(){const root=new T.Group(),green=new T.MeshStandardMaterial({color:'#305e4f',metalness:.3,roughness:.4}),cream=new T.MeshStandardMaterial({color:'#dfd8bd',roughness:.55});box(root,green,0,1,0,2.35,1.5,11);box(root,cream,0,2.36,0,2.35,1.15,10.9);box(root,black,0,3.02,0,2.45,.16,11.2);for(const s of [-1,1]){for(let z=-4.3;z<4.8;z+=1.22)box(root,glass,s*1.185,2.35,z,.035,.86,.96);box(root,glass,0,2.34,s*5.47,1.99,.81,.025);box(root,light,0,1.18,s*5.52,.6,.14,.04);}box(root,chrome,0,3.55,0,.08,1.1,.08);const pant=box(root,chrome,0,3.83,0,1.9,.04,.05);pant.rotation.z=.1;return {root};}
